add_action( 'template_redirect', 'perfectpixel_redirect_search_terms' );

function perfectpixel_redirect_search_terms() {
	if ( ! is_search() || is_admin() ) {
		return;
	}
	$term = mb_strtolower( trim( get_search_query( false ) ) );
	foreach ( explode( '|', '{{search_redirects}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && '' !== $parts[1] && mb_strtolower( $parts[0] ) === $term ) {
			wp_safe_redirect( 0 === strpos( $parts[1], '/' ) ? home_url( $parts[1] ) : $parts[1] );
			exit;
		}
	}
}
